class RiverFlowIntegrationTest {
 static EnvironmentMap generate(double runoff,boolean dry){int n=128;float[] h=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++)h[z*n+x]=(float)(220-z*1.35+Math.pow((x-64)/18.,2)*5);var e=new EnvironmentMap(h);if(dry)e.rain=new float[n*n];var node=new TerrainGraph.Node(1,TerrainGraph.Type.RIVERS,0,0);node.values.put("sources",3.0);node.values.put("headwater",100.0);node.values.put("width",7.0);node.values.put("runoff",runoff);return EnvironmentNodes.apply(node,e,null,n,4096,62,83,()->false);}
 public static void main(String[]a){var low=generate(.2,false);var high=generate(2,false);if(low.ribbons==null||high.ribbons==null||high.riverFlow.residual()>1e-7)throw new AssertionError("Missing water model");double lw=low.ribbons.segments.stream().mapToDouble(s->s.a().radius()*2).average().orElseThrow(),hw=high.ribbons.segments.stream().mapToDouble(s->s.a().radius()*2).average().orElseThrow();if(hw<lw*1.4)throw new AssertionError("Runoff does not affect actual channel width: "+lw+" / "+hw);for(var s:high.ribbons.segments)if(!Double.isFinite(s.a().discharge())||s.b().discharge()+1e-7<s.a().discharge())throw new AssertionError("Discharge lost or decreases along reach");var remapped=high.ribbons.remap(.9,3,62);if(remapped.segments.get(0).a().discharge()!=high.ribbons.segments.get(0).a().discharge())throw new AssertionError("Water remap lost discharge");if(high.share(high.height).riverFlow!=high.riverFlow)throw new AssertionError("Graph node lost budget");var dry=generate(1,true);if(dry.ribbons!=null&&!dry.ribbons.segments.isEmpty())throw new AssertionError("Dry basin generated flowing rivers");System.out.println("PASS: actual generated rivers carry conserved discharge through shaping/remap, runoff widens channels "+lw+" -> "+hw+", dry basin emits no rivers");}
}
